window.until = async (fn, ms = 10000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (fn()) return true; await new Promise((r) => setTimeout(r, 10)) } return false };
window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.radio = (group, label) => { const b = [...document.querySelectorAll('[role=radiogroup][aria-label="' + group + '"] [role=radio]')].find((x) => x.textContent.trim() === label); if (!b) throw new Error('NO RADIO ' + group + '/' + label); b.click() };
window.pick = (title, value) => { const s = document.querySelector('select[title="' + title + '"]'); if (!s) throw new Error('NO SELECT ' + title); const set = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set; set.call(s, value); s.dispatchEvent(new Event('change', { bubbles: true })) };
window.button = (re, root = document) => { const b = [...root.querySelectorAll('button')].find((x) => re.test(x.textContent)); if (!b) throw new Error('NO BUTTON ' + re); b.click() };
window.chart = () => { const rows = [...document.querySelectorAll('[aria-label="Chart table"] [data-row]')]; const circles = [...document.querySelectorAll('[data-dot] circle:last-child')]; return { title: document.querySelector('main h1')?.innerText, sub: document.querySelector('main h1')?.nextElementSibling?.innerText, summary: document.querySelector('[data-summary]')?.innerText ?? null, status: document.querySelector('[role=status]')?.innerText.replace(/\n+/g, ' | ') ?? null, dots: circles.length, fills: [...new Set(circles.map((c) => c.getAttribute('fill')))].slice(0, 4), radii: new Set(circles.map((c) => c.getAttribute('r'))).size, key: document.querySelector('[data-key]')?.innerText.replace(/\n/g, ' ') ?? null, rows: rows.slice(0, 5).map((r) => r.innerText.replace(/\s*\n\s*/g, ' | ')), warn: [...document.querySelectorAll('main .text-warn')].map((e) => e.innerText) } };
window.sig = () => JSON.stringify(chart());
window.act = async (label, fn) => { const before = sig(); const t0 = performance.now(); await fn(); const changed = await until(() => sig() !== before && !/Loading/.test(document.querySelector('main section')?.innerText ?? '')); const ms = Math.round(performance.now() - t0); await sleep(150); return label + ' (' + (changed ? ms + ' ms' : 'NO CHANGE') + ') ' + JSON.stringify(chart()) };
window.timed = async (q) => { const t0 = performance.now(); const r = await window.api.stats.query(q); return { engineMs: r.ms, wallMs: Math.round(performance.now() - t0), rows: r.rows.length, total: r.total } };
